// Conteúdo DEMONSTRATIVO: taxonomia, questões autorais de fundamentos e indicadores ilustrativos.
// Nada aqui é desempenho do aluno. Respostas dadas a estas questões são registradas como
// source:'user' + contentSource:'demo' no histórico pessoal; os indicadores DEMO nunca entram nele.

export const slug = text => String(text).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// Grande área → assunto → subassunto. Extensível: novas entradas criam nós automaticamente.
export const TAXONOMY = [
  ['Clínica Médica', [['Cardiologia', ['Hipertensão arterial', 'Insuficiência cardíaca', 'Síndrome coronariana aguda']], ['Nefrologia', ['Lesão renal aguda', 'Doença renal crônica']]]],
  ['Cirurgia', [['Trauma', ['Atendimento inicial']], ['Abdome agudo', ['Apendicite aguda']]]],
  ['Ginecologia e Obstetrícia', [['Obstetrícia', ['Pré-eclâmpsia', 'Pré-natal']]]],
  ['Pediatria', [['Neonatologia', ['Sala de parto']], ['Puericultura', ['Aleitamento e crescimento']]]],
  ['Medicina Preventiva', [['Epidemiologia', ['Medidas e testes diagnósticos']], ['SUS', ['Princípios e legislação']]]]
].map(([area, topics]) => {
  const areaKey = slug(area);
  return { key: areaKey, label: area, topics: topics.map(([topic, subs]) => {
    const topicKey = `${areaKey}/${slug(topic)}`;
    return { key: topicKey, label: topic, subtopics: subs.map(s => ({ key: `${topicKey}/${slug(s)}`, label: s })) };
  }) };
});

const subIndex = new Map(TAXONOMY.flatMap(a => a.topics.flatMap(t => t.subtopics.map(s => [s.label, { area: a, topic: t, sub: s }]))));
const WHO_HTN = 'https://www.who.int/news-room/fact-sheets/detail/hypertension';

function q(subtopic, id, title, stem, options, correct, explain, analysis, key, ref = null) {
  const { area, topic, sub } = subIndex.get(subtopic);
  return Object.freeze({ id, areaKey: area.key, area: area.label, topicKey: topic.key, topic: topic.label, subtopicKey: sub.key, subtopic: sub.label, title, stem, options, correct, explain, analysis, key, ref });
}

